export default {
  title: 'Actions/Tool bar',
  args: {
    resizable: true,
    enableLogging: false
  },
  argTypes: {
    align: {
      control: 'inline-radio',
      options: ['start', 'end']
    },
    contained: {
      control: 'boolean'
    },
    description: {
      table: { disable: true }
    },
    disabled: {
      control: 'boolean'
    },
    inverted: {
      control: 'boolean'
    },
    items: {
      table: { disable: true }
    },
    itemsOutsideContainer: {
      table: { disable: true }
    },
    resizable: {
      control: 'boolean'
    },
    fill: {
      control: 'inline-radio',
      options: ['ghost', 'outline']
    }
  },
  render: args => {
    const {
      align,
      contained,
      description,
      disabled,
      inverted,
      items,
      resizable,
      fill,
      width,
      itemsOutsideContainer,
      enableLogging
    } = args;
    return html`
      ${description ? html`<p>${description}</p>` : nothing}
      <style>
        ${resizable ? '.container { overflow: auto; resize: horizontal; }' : nothing}
          .container:has(sl-tool-bar:not([contained])) {
          padding: 6px; /* place for focus outline */
        }

        .container:has(sl-tool-bar[inverted]:not([contained])) {
          background: var(--sl-color-background-primary-bold);
          padding: 1.2rem;
        }

        #logging {
          margin-top: 1rem;
          max-height: 300px;
          overflow: auto;
        }
        #logging:not(:empty) {
          border: 1px solid var(--sl-color-border-accent-grey-plain);
          padding: 0.5rem;
        }

        .wrapper {
          display: flex;
          gap: 1rem;
        }

        .container sl-tool-bar {
          flex: ${resizable && !width ? '1 1 0' : '0 1 auto'};
          min-inline-size: 0;
        }
      </style>
      <div class="container">
        <div class="wrapper">
          ${itemsOutsideContainer?.(args)}
          <sl-tool-bar
            ?contained=${contained}
            ?disabled=${disabled}
            ?inverted=${inverted}
            align=${ifDefined(align)}
            fill=${ifDefined(fill)}
            style="inline-size: ${width ?? 'auto'}"
            aria-label="Tool bar example">
            ${items?.(args)}
          </sl-tool-bar>
        </div>
      </div>
      ${enableLogging ? html`<div id="logging"></div>` : nothing}
    `;
  }
} satisfies Meta<Props>;

